public IList<IList<int>> PacificAtlantic(int[][] heights)
{
    int m = heights.Length, n = heights[0].Length;
    var pacific = new bool[m, n];
    var atlantic = new bool[m, n];
    var pacificQueue = new Queue<(int, int)>();
    var atlanticQueue = new Queue<(int, int)>();
    for (int i = 0; i < m; i++)
    {
        pacificQueue.Enqueue((i, 0));
        atlanticQueue.Enqueue((i, n - 1));
        pacific[i, 0] = true;
        atlantic[i, n - 1] = true;
    }
    for (int j = 0; j < n; j++)
    {
        pacificQueue.Enqueue((0, j));
        atlanticQueue.Enqueue((m - 1, j));
        pacific[0, j] = true;
        atlantic[m - 1, j] = true;
    }
    BFS(heights, pacificQueue, pacific);
    BFS(heights, atlanticQueue, atlantic);
    var result = new List<IList<int>>();
    for (int i = 0; i < m; i++)
        for (int j = 0; j < n; j++)
            if (pacific[i, j] && atlantic[i, j])
                result.Add(new List<int> { i, j });
    return result;
}

private void BFS(int[][] heights, Queue<(int, int)> queue, bool[] visited)
{
    int m = heights.Length, n = heights[0].Length;
    int[][] dirs = { new[] { 0, 1 }, new[] { 1, 0 }, new[] { 0, -1 }, new[] { -1, 0 } };
    while (queue.Count > 0)
    {
        var (i, j) = queue.Dequeue();
        foreach (var d in dirs)
        {
            int ni = i + d[0], nj = j + d[1];
            if (ni < 0 || nj < 0 || ni >= m || nj >= n || visited[ni, nj])
                continue;
            if (heights[ni][nj] >= heights[i][j])
            {
                visited[ni, nj] = true;
                queue.Enqueue((ni, nj));
            }
        }
    }
}
